      getImportObject() {
        return {
          wasi_snapshot_preview1: this.wasiImport,
          wasi_unstable: this.wasiImport
        };
      }

      bindMemory(memory) {
        this.memory = memory;
        return this;
      }

      setMemory(memory) {
        this.memory = memory;
        return this;
      }

